import React, {useEffect, useState} from 'react'
import './Home.css'
import { storage } from './Firebase';
import { ref, uploadBytes, listAll, getDownloadURL } from 'firebase/storage'
import { v4 } from 'uuid';


function Home() {





  


   

    const handlehide = () =>
    { 
        let times = document.querySelector( ".mains " )
       
        localStorage.setItem( "main", times )
        times.style.display = "none"
      
    }

    useEffect( () =>
    { 
        let times = document.querySelector( ".mains " )

        if ( localStorage === false )
        { 
           times.style.display = "none" 
        }
         
        
    })

    

    
    const handlekeyup = () =>
    { 
        let chatmess = document.querySelector( ".message" );
        let input_val = document.querySelector( ".input_val" );

        let border_btn = document.querySelector( ".border_btn" );

         var showdate = new Date();
        var displaytoday = showdate.getFullYear();
        var showdate1 = new Date();
        var displaytoday1 = showdate1.getDate();
        var displaytoday2 = showdate1.getMonth();
        var displaytoday3 = showdate1.getDay();
        
        
        let val = document.querySelector( ".like" );
         let val1 = document.querySelector( ".like1" );
         let val2 = document.querySelector( ".like2" );
         let val3 = document.querySelector( ".like3" );

        if ( input_val.value === "" )
        { 
            border_btn.style.borderBottom = "none"
            val.innerHTML = "";
            val1.innerHTML = ""
            val2.innerHTML = ""
            val3.innerHTML = ""
        }

        else
        { 
            border_btn.style.borderBottom = "1px solid #EAEAEA"
            val.innerHTML =   displaytoday;
            val1.innerHTML = "https://www.medzy/" + displaytoday1 + "%";
            val2.innerHTML = displaytoday2 + "%";
            val3.innerHTML = displaytoday3;
        
        }

        

        chatmess.innerHTML = input_val.value;
    }


     const [ imageUpload, setImageUpload ] = useState( null );

  const [ imageList, setImageList ] = useState( [] );

  const imageListRef = ref( storage, "images/" );
  const uploadImage = () =>
  { 

    console.log( imageUpload )
    if ( imageUpload == null ) return;
    const imageRef = ref( storage, `images/${ imageUpload.name + v4() }` );
    
    uploadBytes( imageRef, imageUpload ).then( (snapshot) =>
    { 

      getDownloadURL( snapshot.ref ).then( ( url ) =>
      { 
           setImageList((prev) => [...prev, url])
       })

  
    })

  }

  useEffect( () =>
  { 
    listAll( imageListRef ).then( ( Response ) =>
    { 
      console.log( Response );
      Response.items.forEach( ( item ) =>
      { 
        getDownloadURL( item ).then( ( url ) =>
        { 
          setImageList( (prev) => [...prev,url] );
        } ) 
      })
    })
  },[])

     
   
    

  return (
      <div>
          <div style={{position:"fixed", zIndex: "1000", bottom: "20px", right:"20px"}} className="mains w-50">
              
               <div onClick={handlehide} className=" text-warning cursor-pointer fa fa-times p-2 bg-red w-20 round-  float-right  hover:text-red"></div>

              <div className="text-center shadow-sm p-4 mb-4 bg-white ">
                   <h3 className='text-30 b-2'>Caution</h3>
                  <h2 style={{fontSize: "15px", }}>
                      
                      Welcome!!! This site is Made purposely for uploading and downloading new photos
                  </h2>   
             </div>
          </div>


          <div className="uploadimage">
              <div className="puts">
                  <div className="forms">
                      <form action="" className="form">
                      <i className='fa fa-search'></i>
                      <input className='input_val' onKeyUp={handlekeyup} type="text " placeholder='start chatting with friends' />
                      <button className='btn1 alert-primary'>Submit</button>
                      </form>
                      <br />
                      

                      <div className="chatmessage  shadow-sm   bg-white">
                          
                          <div className="chats">
                              
                              <div className="chatmess">
                                  <div>Chat Message</div>
                                  <p style={ { fontSize: "12px" } }>Posted at: 7:00pm </p>
                                  
                              </div>
                              <hr />
                              <div className="message">
                                 
                              </div>
                              <div className="border_btn"></div>
                              
                              <div className="emotions">
                                  <div>
                                      <span className="like1"></span>
                                      <span className='like2'></span>
                                      <span className='like3'></span>
                                  </div>

                                   <div className="like">
                                     
                                  </div>
                             </div>
                          </div>  
                      </div>

                     
                          

                      <input  type="file" name="" id="files" onChange={(e) =>{setImageUpload(e.target.files[0])}} />
      
                      <button className='btn-success w-150 mt-2 mb-2' onClick={ uploadImage } >Upload</button>
                      

                       { imageList.map( ( url ) =>
                       { 
                           
        return (
                <div className="image_post shadow-sm   bg-white">
                    
                <div className="images">
                     <input  type="file" name="" id="" onChange={(e) =>{setImageUpload(e.target.files[0])}} />
      <br/>
                    <button  className='btn-success w-100' onClick={ uploadImage } >Upload</button>
                    <hr/>
                             <img  src={url} alt="" />
                          </div>
                          <hr/>
                          <div>
                              Posted at: 7:00pm
                          </div>
                </div>
                
        
                           )
                           
                       } ) }
                      
                      
                      
                  </div>

                  
                  
                  
                 
                  
                  
              </div>
          </div>

      </div>
  )
}

export default Home