import React from 'react'
import { Link } from 'react-router-dom'
import './Navbar.css'



function Navbar() {
  return (
    
          <ul className="topnav">
              
              <div className="righter">
                   <li>
                  <img src="https://meritamerica.org/wp-content/uploads/2022/01/fav.png" alt="" />
              </li>
             </div>

              <div className="center">
                  <li>
                  <Link style={{textDecoration:"none", color: "white"}} to="/chat">
                    Chats 
                </Link>
              </li>

              <li>
                  <Link style={{textDecoration:"none", color: "white"}} to="/friends">
                    Friends 
                </Link>
              </li>
              </div>

              <div className="leftbar">
                   <li className='righters'>
                  <i className='fa fa-bars'></i>
              </li>
              </div>
          </ul>

     
  )
}

export default Navbar