import React from 'react'
import './Error.css'

function Error ()
{
    
    const handleUrl = () =>
    { 
        let url = "/";
        let wo = document.querySelector( ".wo" )
        
         setTimeout( () =>
        { 
            wo.innerText = ""
             wo.style.opacity = "0"
        }, )
        

        setTimeout( () =>
        { 
            wo.innerText = "Now That You have clicked on this link"
             wo.style.opacity = "1"
        }, 1000 )

         setTimeout( () =>
        { 
            wo.innerText = "Now That You have clicked on this link"
             wo.style.opacity = "0"
        }, 500)
        
           setTimeout( () =>
        { 
               wo.innerText = "Let's get Ready to be launched to the next page in 3 sec.."
               wo.style.opacity = "1"
           }, 3000 )
        
          setTimeout( () =>
        { 
            wo.innerText = ""
             wo.style.opacity = "0"
          }, 2000 )
        
          setTimeout( () =>
        { 
            wo.innerText = "3"
             wo.style.opacity = "1"
          }, 8000 )
        
        
          setTimeout( () =>
        { 
            wo.innerText = ""
             wo.style.opacity = "0"
          }, 10000 )
        
          setTimeout( () =>
        { 
            wo.innerText = "2"
             wo.style.opacity = "1"
        },10000)
      


          setTimeout( () =>
        { 
            wo.innerText = ""
             wo.style.opacity = "0"
          }, 16000 )
        
        
         setTimeout( () =>
        { 
            wo.innerText = "1"
             wo.style.opacity = "1"
        },19000)

        setTimeout( () =>
        { 
            wo.innerText = " I'm  Sorry! But you Page is not Found"
        window.open( url, "_self" );
        }, 20000 )
        
    }

  return (
      <div className='error'>
          <div className='mainwords'>
              <h1>
                  <div style={{transition: ".5s ease"}} className="wo">
                       I'm  Sorry! But you Page is not Found
                 </div>
                  <button onClick={handleUrl} className='btn'>
                          Head to the main page
                  </button>
              </h1>    
          </div>

      </div>
  )
}

export default Error